insert into public.lesson_content (lesson_id, content) values
  ('m1l1', '{"paragraphs":["Imagine um livro-caixa que milhares de computadores mantêm em conjunto. Quando um grupo de transações é confirmado, a rede acrescenta uma nova página ligada criptograficamente à anterior. Alterar uma página antiga exigiria convencer a rede a reescrever também as seguintes.","Esse registro distribuído é a blockchain. Participantes seguem regras públicas para validar as transações; cada rede define como chega a um acordo. Isso reduz a dependência de um único operador, mas não torna todo projeto confiável nem toda transação reversível.","A rede resolve um problema de coordenação. O preço de um ativo continua dependendo de procura, oferta, utilidade percebida, liquidez e confiança. Tecnologia interessante não é sinônimo de bom investimento."],"takeaway":"A blockchain organiza registros. Ela não garante o valor do que está registrado.","sources":[],"exercise":{"title":"Cheque seu modelo mental","prompt":"Se um bloco já foi confirmado, o que a rede oferece principalmente?","options":["Uma garantia de lucro para quem aparece nele","Um registro compartilhado e difícil de alterar sem o consenso da rede","Um banco central para reverter pagamentos"],"note":"O mecanismo protege a integridade do histórico segundo as regras da rede. Ele não protege o investidor de preço, fraude fora da rede ou erro de envio."},"narration":{"src":"/audio/narrated/m1l1-62c8c891eb14.mp3","captionsSrc":"/audio/narrated/m1l1-62c8c891eb14.json","transcript":"Uma rede que mantém o próprio livro-caixa.\n\nImagine um livro-caixa que milhares de computadores mantêm em conjunto. Quando um grupo de transações é confirmado, a rede acrescenta uma nova página ligada criptograficamente à anterior. Alterar uma página antiga exigiria convencer a rede a reescrever também as seguintes.\n\nEsse registro distribuído é a blockchain. Participantes seguem regras públicas para validar as transações; cada rede define como chega a um acordo. Isso reduz a dependência de um único operador, mas não torna todo projeto confiável nem toda transação reversível.\n\nA rede resolve um problema de coordenação. O preço de um ativo continua dependendo de procura, oferta, utilidade percebida, liquidez e confiança. Tecnologia interessante não é sinônimo de bom investimento.\n\nPara guardar: A blockchain organiza registros. Ela não garante o valor do que está registrado.","summary":"A blockchain organiza registros. Ela não garante o valor do que está registrado.","duration":63.072,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m1l2', '{"paragraphs":["Bitcoin é o ativo nativo de uma rede com regras próprias. Ether é o ativo nativo da Ethereum e também é usado para pagar operações nessa rede. Já um token pode ser criado sobre uma rede existente e pode representar utilidade, governança ou outra promessa definida pelo emissor.","Stablecoins tentam acompanhar o valor de uma referência, como o dólar. Para isso, dependem de reservas, mecanismos e confiança em quem as administra. “Estável” descreve a intenção de preço, não elimina risco de emissor, liquidez, regulação ou descolamento.","Antes de comparar dois ativos, descubra quem pode emitir mais unidades, para que o ativo é usado, quem mantém a infraestrutura e em quais mercados ele pode ser negociado."],"takeaway":"“Cripto” é uma categoria ampla. Identifique o ativo e as regras antes de olhar o gráfico.","sources":[],"exercise":{"title":"Classifique antes de comparar","prompt":"Um token de governança costuma dar ao titular:","options":["Voto em certas decisões do protocolo, conforme regras definidas","Participação garantida nos lucros de uma empresa","Proteção contra queda de preço"],"note":"Direitos variam por projeto e jurisdição. Leia as regras do token; o nome da categoria, sozinho, não cria direitos."},"narration":{"src":"/audio/narrated/m1l2-f2f93656585b.mp3","captionsSrc":"/audio/narrated/m1l2-f2f93656585b.json","transcript":"Bitcoin, ether e tokens: ativos diferentes.\n\nBitcoin é o ativo nativo de uma rede com regras próprias. Ether é o ativo nativo da Ethereum e também é usado para pagar operações nessa rede. Já um token pode ser criado sobre uma rede existente e pode representar utilidade, governança ou outra promessa definida pelo emissor.\n\nStablecoins tentam acompanhar o valor de uma referência, como o dólar. Para isso, dependem de reservas, mecanismos e confiança em quem as administra. “Estável” descreve a intenção de preço, não elimina risco de emissor, liquidez, regulação ou descolamento.\n\nAntes de comparar dois ativos, descubra quem pode emitir mais unidades, para que o ativo é usado, quem mantém a infraestrutura e em quais mercados ele pode ser negociado.\n\nPara guardar: “Cripto” é uma categoria ampla. Identifique o ativo e as regras antes de olhar o gráfico.","summary":"“Cripto” é uma categoria ampla. Identifique o ativo e as regras antes de olhar o gráfico.","duration":62.256,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m1l3', '{"paragraphs":["As moedas não ficam dentro do aplicativo da carteira. O que a carteira protege são as chaves que permitem autorizar operações na blockchain. Uma carteira custodial guarda as chaves por você; uma carteira autocustodial deixa esse controle com você.","Autocustódia acrescenta responsabilidade. A frase de recuperação pode restaurar o acesso e deve permanecer fora de sites, mensagens, fotos e serviços de nuvem. Quem obtém essa frase pode controlar os ativos, e uma transação confirmada normalmente não tem um botão de estorno.","Para começar, pratique com valores pequenos, confirme rede e endereço, entenda taxas e mantenha uma cópia de recuperação offline. Segurança depende também de como você usa o dispositivo e de como verifica o destinatário."],"takeaway":"Controle das chaves traz controle das decisões — e responsabilidade pelos erros.","sources":[],"exercise":{"title":"Regra de custódia","prompt":"Uma pessoa do “suporte” pede sua frase de recuperação para corrigir um erro. O que fazer?","options":["Enviar só as primeiras palavras","Não compartilhar; encerrar contato e verificar o canal oficial por conta própria","Compartilhar se o perfil tiver selo"],"note":"Suporte legítimo não precisa da frase de recuperação. Procure você mesmo o endereço oficial do serviço."},"narration":{"src":"/audio/narrated/m1l3-4f0b37408ddf.mp3","captionsSrc":"/audio/narrated/m1l3-4f0b37408ddf.json","transcript":"Carteiras, chaves e custódia.\n\nAs moedas não ficam dentro do aplicativo da carteira. O que a carteira protege são as chaves que permitem autorizar operações na blockchain. Uma carteira custodial guarda as chaves por você; uma carteira autocustodial deixa esse controle com você.\n\nAutocustódia acrescenta responsabilidade. A frase de recuperação pode restaurar o acesso e deve permanecer fora de sites, mensagens, fotos e serviços de nuvem. Quem obtém essa frase pode controlar os ativos, e uma transação confirmada normalmente não tem um botão de estorno.\n\nPara começar, pratique com valores pequenos, confirme rede e endereço, entenda taxas e mantenha uma cópia de recuperação offline. Segurança depende também de como você usa o dispositivo e de como verifica o destinatário.\n\nPara guardar: Controle das chaves traz controle das decisões — e responsabilidade pelos erros.","summary":"Controle das chaves traz controle das decisões — e responsabilidade pelos erros.","duration":62.016,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m2l1', '{"paragraphs":["Uma exchange aproxima compradores e vendedores, mas cada plataforma tem regras, custos, limites e formas de custódia diferentes. Compare quem opera o serviço, onde está estabelecido, quais ativos e redes oferece e como publica taxas e regras de saque.","Procure histórico verificável de incidentes, avisos de órgãos oficiais, demonstrações de reservas com escopo claro e canais de atendimento que você consiga confirmar fora de anúncios. Nenhum selo ou grande volume substitui sua própria verificação.","Faça um depósito pequeno de teste e entenda como retirar antes de concentrar saldo. Não deixe a facilidade de comprar esconder a pergunta mais importante: como e quando você pode recuperar seus recursos?"],"takeaway":"Confirme identidade, taxas, redes e saques antes de transferir valores relevantes.","sources":[],"exercise":{"title":"Lista de verificação","prompt":"Quais dois dados precisam estar claros antes de comprar?","options":["Taxas totais e condições de saque","Cor do aplicativo e número de seguidores","Promessa de valorização e bônus de cadastro"],"note":"Custos e acesso ao saque afetam sua experiência diretamente. Popularidade não prova segurança."},"narration":{"src":"/audio/narrated/m2l1-bf6693bd11c4.mp3","captionsSrc":"/audio/narrated/m2l1-bf6693bd11c4.json","transcript":"Como avaliar uma exchange.\n\nUma exchange aproxima compradores e vendedores, mas cada plataforma tem regras, custos, limites e formas de custódia diferentes. Compare quem opera o serviço, onde está estabelecido, quais ativos e redes oferece e como publica taxas e regras de saque.\n\nProcure histórico verificável de incidentes, avisos de órgãos oficiais, demonstrações de reservas com escopo claro e canais de atendimento que você consiga confirmar fora de anúncios. Nenhum selo ou grande volume substitui sua própria verificação.\n\nFaça um depósito pequeno de teste e entenda como retirar antes de concentrar saldo. Não deixe a facilidade de comprar esconder a pergunta mais importante: como e quando você pode recuperar seus recursos?\n\nPara guardar: Confirme identidade, taxas, redes e saques antes de transferir valores relevantes.","summary":"Confirme identidade, taxas, redes e saques antes de transferir valores relevantes.","duration":58.968,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m2l2', '{"paragraphs":["Uma ordem a mercado prioriza execução rápida pelo preço disponível. Em um livro raso ou mercado em movimento, o preço final pode diferir do que você viu ao tocar no botão; esse efeito é chamado de slippage.","Uma ordem limitada define o preço máximo de compra ou mínimo de venda que você aceita. Ela pode não ser executada. Uma ordem stop dispara outra ordem quando um nível é alcançado, mas não garante o preço de execução, sobretudo em movimentos rápidos.","Antes de enviar, confira o par negociado, o tipo de ordem, o valor total, as taxas e o efeito de uma execução parcial. Treine com um ambiente simulado e leia como a plataforma implementa cada opção."],"takeaway":"Uma ordem controla instruções de negociação; ela não controla o mercado.","sources":[],"exercise":{"title":"Escolha a instrução","prompt":"Você prefere não pagar acima de um preço definido e pode esperar. Qual ordem combina com essa instrução?","options":["A mercado","Limitada","Stop a mercado"],"note":"A ordem limitada pode ficar sem execução. Escolher um tipo de ordem não torna a tese de investimento melhor."},"narration":{"src":"/audio/narrated/m2l2-8573969fa78c.mp3","captionsSrc":"/audio/narrated/m2l2-8573969fa78c.json","transcript":"Ordens a mercado, limitadas e stop.\n\nUma ordem a mercado prioriza execução rápida pelo preço disponível. Em um livro raso ou mercado em movimento, o preço final pode diferir do que você viu ao tocar no botão; esse efeito é chamado de slippage.\n\nUma ordem limitada define o preço máximo de compra ou mínimo de venda que você aceita. Ela pode não ser executada. Uma ordem stop dispara outra ordem quando um nível é alcançado, mas não garante o preço de execução, sobretudo em movimentos rápidos.\n\nAntes de enviar, confira o par negociado, o tipo de ordem, o valor total, as taxas e o efeito de uma execução parcial. Treine com um ambiente simulado e leia como a plataforma implementa cada opção.\n\nPara guardar: Uma ordem controla instruções de negociação; ela não controla o mercado.","summary":"Uma ordem controla instruções de negociação; ela não controla o mercado.","duration":56.184,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m2l3', '{"paragraphs":["Uma transferência depende de endereço, rede e formato compatíveis. Mesmo duas redes com nomes parecidos podem ser incompatíveis. Transações confirmadas costumam ser irreversíveis; um erro de destino pode significar perda permanente.","Copiar e colar também merece atenção: malware pode substituir um endereço. Confira o começo e o fim do endereço no dispositivo de origem, confirme a rede nos dois lados e verifique se há memo ou tag obrigatória.","Faça um envio pequeno de teste e aguarde a confirmação antes de enviar o restante. Esse cuidado custa uma taxa extra, mas pode revelar um erro de configuração antes que ele fique caro."],"takeaway":"Confira endereço, rede, tag e destinatário; teste antes de aumentar o valor.","sources":[],"exercise":{"title":"Antes de confirmar","prompt":"A exchange e a carteira mostram redes diferentes. Qual é o próximo passo?","options":["Enviar uma pequena parte e torcer","Parar e confirmar compatibilidade com as fontes oficiais dos dois serviços","Escolher a rede mais barata"],"note":"Taxa baixa não compensa uma rede incompatível. Não envie até entender o caminho completo."},"narration":{"src":"/audio/narrated/m2l3-a2a80fcaf4dc.mp3","captionsSrc":"/audio/narrated/m2l3-a2a80fcaf4dc.json","transcript":"A primeira transferência sem improviso.\n\nUma transferência depende de endereço, rede e formato compatíveis. Mesmo duas redes com nomes parecidos podem ser incompatíveis. Transações confirmadas costumam ser irreversíveis; um erro de destino pode significar perda permanente.\n\nCopiar e colar também merece atenção: malware pode substituir um endereço. Confira o começo e o fim do endereço no dispositivo de origem, confirme a rede nos dois lados e verifique se há memo ou tag obrigatória.\n\nFaça um envio pequeno de teste e aguarde a confirmação antes de enviar o restante. Esse cuidado custa uma taxa extra, mas pode revelar um erro de configuração antes que ele fique caro.\n\nPara guardar: Confira endereço, rede, tag e destinatário; teste antes de aumentar o valor.","summary":"Confira endereço, rede, tag e destinatário; teste antes de aumentar o valor.","duration":54.648,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m8l1', '{"paragraphs":["“Comprar Bitcoin” pode significar adquirir o ativo à vista em uma exchange, negociar uma cota de fundo ou ETF que acompanha uma referência de cripto, ou negociar diretamente com outra pessoa. Esses caminhos têm direitos, custos, horários, riscos e formas de custódia diferentes.","Na compra à vista, o saldo pode ser mantido pela exchange ou retirado para uma carteira própria, conforme regras e redes disponíveis. Uma cota negociada na bolsa dá exposição conforme a estrutura do produto, mas não entrega as chaves nem necessariamente permite resgate em BTC. Leia regulamento, índice, taxas e documentos atuais.","No P2P, você negocia com uma contraparte. Escrow, reputação e comprovantes ajudam a organizar a operação, mas não removem fraude, disputa, bloqueio bancário ou risco de contraparte. Cartão, Pix e transferência também podem ter custos e regras diferentes por plataforma."],"takeaway":"Compare o que você recebe e quem controla as chaves antes de comparar apenas o preço.","sources":[{"label":"B3: diferenças entre comprar diretamente, ETF e futuro de Bitcoin","url":"https://borainvestir.b3.com.br/tipos-de-investimentos/renda-variavel/criptoativos/futuro-de-bitcoin-etf-de-bitcoin-ou-comprar-diretamente-entenda-as-diferencas-desses-investimentos/"},{"label":"B3: ETFs de criptoativos e fatores para analisar","url":"https://borainvestir.b3.com.br/tipos-de-investimentos/renda-variavel/criptoativos/7-coisas-que-voce-precisa-saber-antes-de-investir-em-etfs-de-criptoativos/"}],"exercise":{"title":"Escolha o que comparar","prompt":"Você quer entender se uma cota de ETF é equivalente a manter BTC em carteira própria. Qual pergunta ajuda mais?","options":["A cota dá controle de chaves ou resgate em Bitcoin? Quais são suas regras e custos?","Qual ativo teve a maior alta nesta semana?","Qual produto tem o nome mais parecido com Bitcoin?"],"note":"Exposição econômica, propriedade de cotas e custódia direta são coisas diferentes. Verifique documentos do produto."},"narration":{"src":"/audio/narrated/m8l1-2bf7635d1e68.mp3","captionsSrc":"/audio/narrated/m8l1-2bf7635d1e68.json","transcript":"Bitcoin à vista, ETF ou P2P?.\n\n“Comprar Bitcoin” pode significar adquirir o ativo à vista em uma exchange, negociar uma cota de fundo ou ETF que acompanha uma referência de cripto, ou negociar diretamente com outra pessoa. Esses caminhos têm direitos, custos, horários, riscos e formas de custódia diferentes.\n\nNa compra à vista, o saldo pode ser mantido pela exchange ou retirado para uma carteira própria, conforme regras e redes disponíveis. Uma cota negociada na bolsa dá exposição conforme a estrutura do produto, mas não entrega as chaves nem necessariamente permite resgate em BTC. Leia regulamento, índice, taxas e documentos atuais.\n\nNo P2P, você negocia com uma contraparte. Escrow, reputação e comprovantes ajudam a organizar a operação, mas não removem fraude, disputa, bloqueio bancário ou risco de contraparte. Cartão, Pix e transferência também podem ter custos e regras diferentes por plataforma.\n\nPara guardar: Compare o que você recebe e quem controla as chaves antes de comparar apenas o preço.","summary":"Compare o que você recebe e quem controla as chaves antes de comparar apenas o preço.","duration":73.728,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m8l2', '{"paragraphs":["1. Escolha o caminho e confirme que entende o produto. 2. Verifique a empresa ou intermediário em fontes oficiais, acesse o endereço por conta própria e habilite autenticação forte. 3. Compare taxa de negociação, spread, depósito, saque, rede e custo total.","4. Planeje um valor que não comprometa despesas, dívidas ou reserva. Se decidir seguir, comece pelo fluxo de menor complexidade disponível; confira ativo, par, total em reais, tipo de ordem e taxa na tela final. Não aceite pressão ou promessa de rentabilidade.","5. Depois, confira o extrato e salve comprovantes. Se retirar BTC para autocustódia, valide endereço e rede, faça primeiro um envio pequeno e confirme o recebimento. Transferências confirmadas em blockchain normalmente não têm estorno."],"takeaway":"Use uma lista de verificação; não decida sob urgência ou por promessa de retorno.","sources":[],"exercise":{"title":"Antes de confirmar","prompt":"Uma pessoa no direct oferece “ajudar” e pede que você compartilhe a tela para comprar Bitcoin. O que fazer?","options":["Recusar, encerrar a conversa e abrir o canal oficial por conta própria","Aceitar se ela conhece o nome da exchange","Compartilhar a tela, mas ocultar o saldo"],"note":"Não entregue senhas, códigos, seed phrase nem controle remoto. Suporte legítimo não precisa da sua chave privada."},"narration":{"src":"/audio/narrated/m8l2-da5e0321c195.mp3","captionsSrc":"/audio/narrated/m8l2-da5e0321c195.json","transcript":"Uma compra simulada do começo ao fim.\n\n1. Escolha o caminho e confirme que entende o produto. 2. Verifique a empresa ou intermediário em fontes oficiais, acesse o endereço por conta própria e habilite autenticação forte. 3. Compare taxa de negociação, spread, depósito, saque, rede e custo total.\n\n4. Planeje um valor que não comprometa despesas, dívidas ou reserva. Se decidir seguir, comece pelo fluxo de menor complexidade disponível; confira ativo, par, total em reais, tipo de ordem e taxa na tela final. Não aceite pressão ou promessa de rentabilidade.\n\n5. Depois, confira o extrato e salve comprovantes. Se retirar BTC para autocustódia, valide endereço e rede, faça primeiro um envio pequeno e confirme o recebimento. Transferências confirmadas em blockchain normalmente não têm estorno.\n\nPara guardar: Use uma lista de verificação; não decida sob urgência ou por promessa de retorno.","summary":"Use uma lista de verificação; não decida sob urgência ou por promessa de retorno.","duration":68.088,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m8l3', '{"paragraphs":["Decida onde o ativo fica guardado. Manter saldo na exchange depende dos controles, solvência, disponibilidade de saques e regras da empresa. Autocustódia transfere a responsabilidade das chaves para você e exige cópias de recuperação seguras e procedimentos testados.","Uma tela de saldo não é histórico suficiente. Guarde data, valor em reais, quantidade, taxa, comprovante e, quando houver, identificador da transação. Isso ajuda a explicar custos e movimentações futuras; obrigações fiscais dependem das regras vigentes e do seu caso.","Um plano de aportes periódicos pode organizar decisões no tempo, mas não garante lucro, reduz todas as perdas nem torna o preço previsível. Reveja objetivos e limites sem transformar uma rotina em compra automática que você não entende."],"takeaway":"Comprar é só uma etapa. Registro, acesso e plano de segurança também fazem parte.","sources":[{"label":"Banco Central: informações e alertas sobre criptoativos","url":"https://www.bcb.gov.br/estabilidadefinanceira/criptoativos"}],"exercise":{"title":"Organize sua trilha de auditoria","prompt":"Qual registro é mais útil para acompanhar uma compra?","options":["Data, valor em reais, quantidade, taxa, comprovante e eventual hash","Uma captura do preço atual","Só o nome do ativo"],"note":"Registros completos ajudam a entender operações e podem ser úteis para obrigações fiscais. Consulte a regra oficial vigente."},"narration":{"src":"/audio/narrated/m8l3-07249ffc02b4.mp3","captionsSrc":"/audio/narrated/m8l3-07249ffc02b4.json","transcript":"Depois da compra: registro e custódia.\n\nDecida onde o ativo fica guardado. Manter saldo na exchange depende dos controles, solvência, disponibilidade de saques e regras da empresa. Autocustódia transfere a responsabilidade das chaves para você e exige cópias de recuperação seguras e procedimentos testados.\n\nUma tela de saldo não é histórico suficiente. Guarde data, valor em reais, quantidade, taxa, comprovante e, quando houver, identificador da transação. Isso ajuda a explicar custos e movimentações futuras; obrigações fiscais dependem das regras vigentes e do seu caso.\n\nUm plano de aportes periódicos pode organizar decisões no tempo, mas não garante lucro, reduz todas as perdas nem torna o preço previsível. Reveja objetivos e limites sem transformar uma rotina em compra automática que você não entende.\n\nPara guardar: Comprar é só uma etapa. Registro, acesso e plano de segurança também fazem parte.","summary":"Comprar é só uma etapa. Registro, acesso e plano de segurança também fazem parte.","duration":67.512,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m3l1', '{"paragraphs":["Toda análise começa com uma hipótese verificável. Que problema o projeto tenta resolver? Quem tem esse problema? Por que essa rede ou aplicação seria útil, e o que mudaria se o token deixasse de existir?","Leia a documentação original e identifique o que já funciona, o que ainda é promessa e quem mantém o projeto. Diferencie código aberto, auditorias, uso real e linguagem promocional; cada item informa algo distinto e nenhum, sozinho, elimina o risco.","Escreva sua tese em poucas linhas e anote o que a refutaria. Uma tese que não admite evidência contrária vira torcida, não método."],"takeaway":"Uma tese útil pode ser questionada e atualizada quando surgem fatos novos.","sources":[],"exercise":{"title":"Teste de hipótese","prompt":"Qual frase permite pesquisa mais objetiva?","options":["“Esse token vai subir porque todo mundo fala dele.”","“A aplicação processa X operações; vou verificar usuários, custos e concentração.”","“O fundador parece confiante.”"],"note":"Uma hipótese observável permite comparar discurso com dados e revisar a conclusão."},"narration":{"src":"/audio/narrated/m3l1-23c289b19492.mp3","captionsSrc":"/audio/narrated/m3l1-23c289b19492.json","transcript":"Comece pelo problema, não pelo preço.\n\nToda análise começa com uma hipótese verificável. Que problema o projeto tenta resolver? Quem tem esse problema? Por que essa rede ou aplicação seria útil, e o que mudaria se o token deixasse de existir?\n\nLeia a documentação original e identifique o que já funciona, o que ainda é promessa e quem mantém o projeto. Diferencie código aberto, auditorias, uso real e linguagem promocional; cada item informa algo distinto e nenhum, sozinho, elimina o risco.\n\nEscreva sua tese em poucas linhas e anote o que a refutaria. Uma tese que não admite evidência contrária vira torcida, não método.\n\nPara guardar: Uma tese útil pode ser questionada e atualizada quando surgem fatos novos.","summary":"Uma tese útil pode ser questionada e atualizada quando surgem fatos novos.","duration":53.352,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m3l2', '{"paragraphs":["A oferta em circulação é apenas uma parte da história. Veja o total máximo ou previsto, os cronogramas de emissão e desbloqueio, quem controla grandes carteiras e quais incentivos distribuem tokens a equipe, investidores ou usuários.","Um valor de mercado totalmente diluído pode destacar o efeito de toda a oferta prevista ao preço atual. Ele não significa que essa oferta possa ser vendida por esse preço; liquidez e profundidade do mercado mudam o resultado.","Pergunte quem recebe novos tokens, quando pode vendê-los e que demanda sustentaria a utilidade. Compare o fluxo de desbloqueios com a profundidade negociada e não trate escassez anunciada como prova de valorização."],"takeaway":"Oferta, concentração e liquidez ajudam a entender quem pode vender e a que custo.","sources":[],"exercise":{"title":"Encontre a pergunta certa","prompt":"O projeto anuncia um limite de oferta. O que ainda vale investigar?","options":["Quem já possui tokens e quando eles podem ser desbloqueados","Somente a cor do símbolo","Se o nome aparece em uma lista de tendências"],"note":"O cronograma de emissão e a distribuição podem mudar incentivos e pressão de venda."},"narration":{"src":"/audio/narrated/m3l2-2a5bc90839ac.mp3","captionsSrc":"/audio/narrated/m3l2-2a5bc90839ac.json","transcript":"Oferta, desbloqueios e liquidez.\n\nA oferta em circulação é apenas uma parte da história. Veja o total máximo ou previsto, os cronogramas de emissão e desbloqueio, quem controla grandes carteiras e quais incentivos distribuem tokens a equipe, investidores ou usuários.\n\nUm valor de mercado totalmente diluído pode destacar o efeito de toda a oferta prevista ao preço atual. Ele não significa que essa oferta possa ser vendida por esse preço; liquidez e profundidade do mercado mudam o resultado.\n\nPergunte quem recebe novos tokens, quando pode vendê-los e que demanda sustentaria a utilidade. Compare o fluxo de desbloqueios com a profundidade negociada e não trate escassez anunciada como prova de valorização.\n\nPara guardar: Oferta, concentração e liquidez ajudam a entender quem pode vender e a que custo.","summary":"Oferta, concentração e liquidez ajudam a entender quem pode vender e a que custo.","duration":56.352,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m3l3', '{"paragraphs":["Volume, usuários ativos, taxas e valor total bloqueado são medidas diferentes. Verifique como cada painel calcula seus números, se a métrica pode incluir atividade automatizada e se houve mudança de metodologia.","Cruze a documentação do projeto com exploradores da rede, dados independentes e comunicados verificáveis. Uma manchete ou captura de tela não revela contexto, período, fonte nem conflito de interesse.","Guarde a data das evidências e faça perguntas incômodas: o dado continua crescendo depois de incentivos? A atividade vem de poucos endereços? O preço depende de uma única exchange?"],"takeaway":"Métrica sem definição e fonte verificável é uma afirmação, não evidência.","sources":[],"exercise":{"title":"Pese a evidência","prompt":"Um gráfico viral mostra “usuários recordes”. Qual verificação vem primeiro?","options":["Abrir a fonte, o período e a definição de usuário","Repassar o gráfico para não perder a alta","Presumir que usuários são pessoas únicas"],"note":"Métricas on-chain podem contar endereços e contratos, não pessoas."},"narration":{"src":"/audio/narrated/m3l3-8e56cb585a01.mp3","captionsSrc":"/audio/narrated/m3l3-8e56cb585a01.json","transcript":"Dados, fontes e sinais de alerta.\n\nVolume, usuários ativos, taxas e valor total bloqueado são medidas diferentes. Verifique como cada painel calcula seus números, se a métrica pode incluir atividade automatizada e se houve mudança de metodologia.\n\nCruze a documentação do projeto com exploradores da rede, dados independentes e comunicados verificáveis. Uma manchete ou captura de tela não revela contexto, período, fonte nem conflito de interesse.\n\nGuarde a data das evidências e faça perguntas incômodas: o dado continua crescendo depois de incentivos? A atividade vem de poucos endereços? O preço depende de uma única exchange?\n\nPara guardar: Métrica sem definição e fonte verificável é uma afirmação, não evidência.","summary":"Métrica sem definição e fonte verificável é uma afirmação, não evidência.","duration":53.304,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m4l1', '{"paragraphs":["Capacidade de risco é o que suas finanças suportam sem comprometer necessidades e planos. Tolerância é como você se sente diante da oscilação. Uma pessoa pode tolerar uma queda emocionalmente, mas não ter capacidade de esperar pela recuperação.","Separe reserva de emergência, despesas próximas e dívidas do capital especulativo. Não use dinheiro necessário para aluguel, saúde ou obrigações. Se perder o valor alteraria sua rotina, o tamanho provavelmente está grande demais para seu contexto.","Criptoativos podem perder grande parte ou todo o valor. Antes de investir, considere também risco de plataforma, custódia, fraude, liquidez, tecnologia e regulação."],"takeaway":"Defina primeiro o que não pode ser comprometido.","sources":[],"exercise":{"title":"Ordene as prioridades","prompt":"Você ainda não tem reserva para despesas essenciais. Qual próximo passo é mais prudente?","options":["Definir a reserva e o orçamento antes de pensar em ativos voláteis","Usar o limite do cartão para não perder oportunidade","Escolher a moeda com maior alta recente"],"note":"Prioridades financeiras vêm antes de uma estratégia de investimento especulativo."},"narration":{"src":"/audio/narrated/m4l1-2b635e17b243.mp3","captionsSrc":"/audio/narrated/m4l1-2b635e17b243.json","transcript":"Capacidade de risco e dinheiro necessário.\n\nCapacidade de risco é o que suas finanças suportam sem comprometer necessidades e planos. Tolerância é como você se sente diante da oscilação. Uma pessoa pode tolerar uma queda emocionalmente, mas não ter capacidade de esperar pela recuperação.\n\nSepare reserva de emergência, despesas próximas e dívidas do capital especulativo. Não use dinheiro necessário para aluguel, saúde ou obrigações. Se perder o valor alteraria sua rotina, o tamanho provavelmente está grande demais para seu contexto.\n\nCriptoativos podem perder grande parte ou todo o valor. Antes de investir, considere também risco de plataforma, custódia, fraude, liquidez, tecnologia e regulação.\n\nPara guardar: Defina primeiro o que não pode ser comprometido.","summary":"Defina primeiro o que não pode ser comprometido.","duration":56.88,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m4l2', '{"paragraphs":["Uma posição pequena o bastante para ser ignorada tende a ser mais administrável do que uma que domina sua atenção. Uma maneira de visualizar isso é perguntar: se o ativo caísse 50%, que valor seria perdido e que decisões essa perda provocaria?","Não existe tamanho universal. Horizontes, renda, obrigações, experiência e diversificação importam. Stop, limite de perda e ordens automáticas podem falhar em gaps, falta de liquidez e indisponibilidade de plataforma.","Use a simulação ao lado para tornar o impacto visível. Ela não estima a probabilidade de cada cenário nem recomenda percentual; serve apenas para testar se você entende o que uma oscilação significa em reais."],"takeaway":"Pense em perda possível em reais antes de pensar em retorno percentual.","sources":[],"exercise":{"title":"Uma regra que ajuda","prompt":"Por que simular uma queda antes de comprar?","options":["Para provar que a queda não acontecerá","Para estimar impacto e checar se ele cabe no orçamento","Para descobrir o melhor momento de entrada"],"note":"A simulação é educativa e não prevê preço nem probabilidade de mercado."},"narration":{"src":"/audio/narrated/m4l2-2809ccab0ad9.mp3","captionsSrc":"/audio/narrated/m4l2-2809ccab0ad9.json","transcript":"Dimensione pelo prejuízo que tolera.\n\nUma posição pequena o bastante para ser ignorada tende a ser mais administrável do que uma que domina sua atenção. Uma maneira de visualizar isso é perguntar: se o ativo caísse 50%, que valor seria perdido e que decisões essa perda provocaria?\n\nNão existe tamanho universal. Horizontes, renda, obrigações, experiência e diversificação importam. Stop, limite de perda e ordens automáticas podem falhar em gaps, falta de liquidez e indisponibilidade de plataforma.\n\nUse a simulação ao lado para tornar o impacto visível. Ela não estima a probabilidade de cada cenário nem recomenda percentual; serve apenas para testar se você entende o que uma oscilação significa em reais.\n\nPara guardar: Pense em perda possível em reais antes de pensar em retorno percentual.","summary":"Pense em perda possível em reais antes de pensar em retorno percentual.","duration":57.888,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m4l3', '{"paragraphs":["Aportes periódicos, chamados de DCA, distribuem compras em datas planejadas. Podem reduzir a dependência de uma única data, mas não garantem lucro, não evitam perdas e podem resultar em retorno inferior a outras estratégias dependendo do mercado.","Diversificar significa não depender de uma única tese ou fonte de risco. Ter muitos tokens correlacionados não é diversificação real; examine exposição por rede, setor, custodiante e liquidez.","Defina uma rotina de revisão: frequência, dados que acompanham a tese e eventos que pedem reavaliação. Evite mudar o plano a cada manchete; atualize quando a evidência importante mudar."],"takeaway":"Uma rotina pode organizar decisões. Ela não remove risco de mercado.","sources":[],"exercise":{"title":"Escolha o uso adequado","prompt":"Qual afirmação sobre DCA é correta?","options":["Garante preço médio baixo e lucro","Automatiza compras em datas planejadas, sem garantir resultado","Funciona apenas com stablecoins"],"note":"DCA muda a distribuição temporal das compras; não elimina risco nem substitui análise."},"narration":{"src":"/audio/narrated/m4l3-3f79c603c79b.mp3","captionsSrc":"/audio/narrated/m4l3-3f79c603c79b.json","transcript":"Aportes periódicos, diversificação e revisão.\n\nAportes periódicos, chamados de DCA, distribuem compras em datas planejadas. Podem reduzir a dependência de uma única data, mas não garantem lucro, não evitam perdas e podem resultar em retorno inferior a outras estratégias dependendo do mercado.\n\nDiversificar significa não depender de uma única tese ou fonte de risco. Ter muitos tokens correlacionados não é diversificação real; examine exposição por rede, setor, custodiante e liquidez.\n\nDefina uma rotina de revisão: frequência, dados que acompanham a tese e eventos que pedem reavaliação. Evite mudar o plano a cada manchete; atualize quando a evidência importante mudar.\n\nPara guardar: Uma rotina pode organizar decisões. Ela não remove risco de mercado.","summary":"Uma rotina pode organizar decisões. Ela não remove risco de mercado.","duration":57.096,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m5l1', '{"paragraphs":["Golpistas costumam combinar urgência, autoridade e uma promessa atraente: sorteio, airdrop, suporte, vaga de investimento ou recuperação de carteira. A história muda; a pressão para agir antes de verificar se repete.","Rug pull, phishing e falso suporte exploram pontos diferentes. Em todos, confira o domínio por um canal independente, pesquise a equipe e a operação, leia o que você está assinando e interrompa qualquer processo que peça uma transferência urgente.","Desconfie de lucro garantido, retorno extraordinário ou “última chance”. Alertas da CVM sobre criptoativos e ofertas irregulares são uma boa referência para reconhecer sinais de fraude."],"takeaway":"Pressa é um sinal para parar, confirmar e procurar a fonte por conta própria.","sources":[],"exercise":{"title":"Classifique o sinal","prompt":"Um perfil promete dobrar o depósito em 48 horas se você enviar agora. Como agir?","options":["Enviar uma quantia pequena para testar","Não enviar; verificar oferta e responsável em fontes oficiais","Pedir ao perfil uma captura de tela de lucro"],"note":"Promessas de ganho alto e rápido sem risco são forte sinal de alerta. Não envie fundos."},"narration":{"src":"/audio/narrated/m5l1-a1f4ca09580b.mp3","captionsSrc":"/audio/narrated/m5l1-a1f4ca09580b.json","transcript":"Golpes que começam com pressa.\n\nGolpistas costumam combinar urgência, autoridade e uma promessa atraente: sorteio, airdrop, suporte, vaga de investimento ou recuperação de carteira. A história muda; a pressão para agir antes de verificar se repete.\n\nRug pull, phishing e falso suporte exploram pontos diferentes. Em todos, confira o domínio por um canal independente, pesquise a equipe e a operação, leia o que você está assinando e interrompa qualquer processo que peça uma transferência urgente.\n\nDesconfie de lucro garantido, retorno extraordinário ou “última chance”. Alertas da CVM sobre criptoativos e ofertas irregulares são uma boa referência para reconhecer sinais de fraude.\n\nPara guardar: Pressa é um sinal para parar, confirmar e procurar a fonte por conta própria.","summary":"Pressa é um sinal para parar, confirmar e procurar a fonte por conta própria.","duration":54.456,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m5l2', '{"paragraphs":["Conectar uma carteira a um site pode expor muito além do endereço público. Uma assinatura pode autorizar ações e permissões de contrato inteligente podem deixar um aplicativo movimentar tokens no futuro.","Use favoritos salvos para serviços importantes, verifique o domínio letra por letra e entenda a mensagem de assinatura. Não conecte a carteira principal a páginas encontradas em comentários, anúncios ou mensagens diretas.","Mantenha uma carteira separada para experimentos e revise autorizações que não usa mais com ferramentas oficiais da rede. Revogar uma permissão não recupera fundos já transferidos."],"takeaway":"Ler uma assinatura e conferir o domínio são parte de cada interação com Web3.","sources":[],"exercise":{"title":"Antes de assinar","prompt":"A página pede uma assinatura que você não consegue explicar. O que fazer?","options":["Recusar e entender a solicitação por uma fonte independente","Aceitar se o saldo não mudou na tela","Desativar o antivírus"],"note":"Não assine instruções que não entende; mensagens podem autorizar operações relevantes."},"narration":{"src":"/audio/narrated/m5l2-dbe0adc5714a.mp3","captionsSrc":"/audio/narrated/m5l2-dbe0adc5714a.json","transcript":"Assinaturas, permissões e links.\n\nConectar uma carteira a um site pode expor muito além do endereço público. Uma assinatura pode autorizar ações e permissões de contrato inteligente podem deixar um aplicativo movimentar tokens no futuro.\n\nUse favoritos salvos para serviços importantes, verifique o domínio letra por letra e entenda a mensagem de assinatura. Não conecte a carteira principal a páginas encontradas em comentários, anúncios ou mensagens diretas.\n\nMantenha uma carteira separada para experimentos e revise autorizações que não usa mais com ferramentas oficiais da rede. Revogar uma permissão não recupera fundos já transferidos.\n\nPara guardar: Ler uma assinatura e conferir o domínio são parte de cada interação com Web3.","summary":"Ler uma assinatura e conferir o domínio são parte de cada interação com Web3.","duration":50.64,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m5l3', '{"paragraphs":["Use senhas únicas em um gerenciador confiável, autenticação em dois fatores por aplicativo ou chave física e atualizações regulares. SMS é vulnerável a troca indevida de chip; use uma alternativa mais forte quando disponível.","Separe dispositivos ou carteiras por função e mantenha cópias de recuperação protegidas de acesso digital. Pratique o processo de recuperação sem expor segredos e confirme instruções nos sites oficiais.","Se suspeitar de comprometimento, pare de assinar, não responda ao invasor, acesse a conta por canal oficial e procure ajuda independente. Registre horários e transações; não pague “taxa de resgate” para quem promete recuperar fundos."],"takeaway":"Segurança eficaz é uma rotina praticada antes do incidente.","sources":[],"exercise":{"title":"Primeira resposta","prompt":"Você percebe uma transação que não reconhece. O que vem primeiro?","options":["Interromper novas assinaturas e acessar o serviço pelo canal oficial","Clicar no primeiro anúncio de recuperação","Mandar a frase-semente ao suporte"],"note":"Evite novos danos e confirme o canal oficial antes de qualquer ação."},"narration":{"src":"/audio/narrated/m5l3-a73e55a910d6.mp3","captionsSrc":"/audio/narrated/m5l3-a73e55a910d6.json","transcript":"Sua rotina de segurança e plano de resposta.\n\nUse senhas únicas em um gerenciador confiável, autenticação em dois fatores por aplicativo ou chave física e atualizações regulares. SMS é vulnerável a troca indevida de chip; use uma alternativa mais forte quando disponível.\n\nSepare dispositivos ou carteiras por função e mantenha cópias de recuperação protegidas de acesso digital. Pratique o processo de recuperação sem expor segredos e confirme instruções nos sites oficiais.\n\nSe suspeitar de comprometimento, pare de assinar, não responda ao invasor, acesse a conta por canal oficial e procure ajuda independente. Registre horários e transações; não pague “taxa de resgate” para quem promete recuperar fundos.\n\nPara guardar: Segurança eficaz é uma rotina praticada antes do incidente.","summary":"Segurança eficaz é uma rotina praticada antes do incidente.","duration":56.232,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m6l1', '{"paragraphs":["Finanças descentralizadas reúnem protocolos que executam regras financeiras em contratos inteligentes. Uma exchange descentralizada pode trocar tokens por meio de pools; um protocolo de empréstimo pode usar garantias para automatizar crédito.","O código pode ser público sem ser seguro. Bugs, chaves administrativas, oráculos, pontes entre redes, liquidez baixa e incentivos temporários criam riscos distintos. Auditoria reduz algumas incertezas, mas não certifica que perdas não ocorrerão.","Antes de interagir, descubra qual contrato recebe seus ativos, como encerrar a posição, que permissões está concedendo e quais dependências podem falhar. Comece estudando o fluxo em uma rede de testes."],"takeaway":"“Sem intermediário” transfere mais operações e riscos para o usuário.","sources":[],"exercise":{"title":"Encontre a dependência","prompt":"Um protocolo usa um preço externo para liquidar posições. Qual componente também merece análise?","options":["O oráculo e suas fontes de preço","A cor da página","O número de curtidas da equipe"],"note":"Dados externos são uma dependência técnica e podem falhar ou ser manipulados."},"narration":{"src":"/audio/narrated/m6l1-56c0f52d6177.mp3","captionsSrc":"/audio/narrated/m6l1-56c0f52d6177.json","transcript":"DeFi: contratos, protocolos e dependências.\n\nFinanças descentralizadas reúnem protocolos que executam regras financeiras em contratos inteligentes. Uma exchange descentralizada pode trocar tokens por meio de pools; um protocolo de empréstimo pode usar garantias para automatizar crédito.\n\nO código pode ser público sem ser seguro. Bugs, chaves administrativas, oráculos, pontes entre redes, liquidez baixa e incentivos temporários criam riscos distintos. Auditoria reduz algumas incertezas, mas não certifica que perdas não ocorrerão.\n\nAntes de interagir, descubra qual contrato recebe seus ativos, como encerrar a posição, que permissões está concedendo e quais dependências podem falhar. Comece estudando o fluxo em uma rede de testes.\n\nPara guardar: “Sem intermediário” transfere mais operações e riscos para o usuário.","summary":"“Sem intermediário” transfere mais operações e riscos para o usuário.","duration":60.288,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m6l2', '{"paragraphs":["Staking ajuda certas redes a validar blocos; suas regras podem incluir período de saída, variação da recompensa e penalidade por comportamento inválido do validador. Um serviço custodial de staking acrescenta risco de contraparte.","Emprestar tokens, fornecer liquidez e fazer yield farming são atividades diferentes. Liquidez em pools pode sofrer perda impermanente e exposição a ativos com preços que mudam em ritmos diferentes. Recompensas altas podem refletir risco, emissão inflacionária ou incentivos temporários.","Compare retorno anunciado com origem das recompensas, riscos de contrato, custos de saída, liquidez e cenário de perda. Não confunda taxa exibida com resultado líquido nem anualize um período curto como se fosse garantido."],"takeaway":"Toda recompensa tem origem e condições. Descubra ambas antes de avaliar o número.","sources":[],"exercise":{"title":"Leia a recompensa","prompt":"Um protocolo anuncia 80% ao ano em tokens recém-emitidos. O que investigar?","options":["De onde vem a recompensa e qual diluição, liquidez e risco de contrato existem","Somente quantas pessoas estão divulgando","Quanto tempo falta para entrar"],"note":"A taxa pode não ser sustentável e pode ser superada por perdas ou queda do token."},"narration":{"src":"/audio/narrated/m6l2-b784f4101ef4.mp3","captionsSrc":"/audio/narrated/m6l2-b784f4101ef4.json","transcript":"Staking, empréstimos e provisão de liquidez.\n\nStaking ajuda certas redes a validar blocos; suas regras podem incluir período de saída, variação da recompensa e penalidade por comportamento inválido do validador. Um serviço custodial de staking acrescenta risco de contraparte.\n\nEmprestar tokens, fornecer liquidez e fazer yield farming são atividades diferentes. Liquidez em pools pode sofrer perda impermanente e exposição a ativos com preços que mudam em ritmos diferentes. Recompensas altas podem refletir risco, emissão inflacionária ou incentivos temporários.\n\nCompare retorno anunciado com origem das recompensas, riscos de contrato, custos de saída, liquidez e cenário de perda. Não confunda taxa exibida com resultado líquido nem anualize um período curto como se fosse garantido.\n\nPara guardar: Toda recompensa tem origem e condições. Descubra ambas antes de avaliar o número.","summary":"Toda recompensa tem origem e condições. Descubra ambas antes de avaliar o número.","duration":64.176,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m6l3', '{"paragraphs":["A forma de declarar ou tributar ativos virtuais depende do tipo de operação, da localização da custodiante, das normas vigentes e da situação de cada pessoa. Uma transação pode gerar obrigações distintas de manter um saldo parado.","Guarde extratos, comprovantes, datas, valores em reais, taxas, endereços e a identificação da plataforma. Registros organizados ajudam a reconstruir o custo de aquisição e a explicar movimentações entre carteiras próprias.","As regras brasileiras mudam. Consulte as páginas de criptoativos e a DeCripto da Receita Federal na data da operação; procure um contador para análise do seu caso. Esta aula organiza perguntas e registros, não substitui orientação tributária."],"takeaway":"Registre cada operação e confirme a regra oficial vigente antes de declarar.","sources":[],"exercise":{"title":"Prepare seus registros","prompt":"Qual conjunto é mais útil para reconstruir uma operação?","options":["Data, ativo, quantidade, custo em reais, taxa e comprovante","Apenas o preço lembrado no fim do ano","Uma captura de tela do saldo atual"],"note":"O histórico detalhado e os comprovantes ajudam a explicar compras, vendas e transferências."},"narration":{"src":"/audio/narrated/m6l3-64374babdf84.mp3","captionsSrc":"/audio/narrated/m6l3-64374babdf84.json","transcript":"Registros e impostos no Brasil.\n\nA forma de declarar ou tributar ativos virtuais depende do tipo de operação, da localização da custodiante, das normas vigentes e da situação de cada pessoa. Uma transação pode gerar obrigações distintas de manter um saldo parado.\n\nGuarde extratos, comprovantes, datas, valores em reais, taxas, endereços e a identificação da plataforma. Registros organizados ajudam a reconstruir o custo de aquisição e a explicar movimentações entre carteiras próprias.\n\nAs regras brasileiras mudam. Consulte as páginas de criptoativos e a DeCripto da Receita Federal na data da operação; procure um contador para análise do seu caso. Esta aula organiza perguntas e registros, não substitui orientação tributária.\n\nPara guardar: Registre cada operação e confirme a regra oficial vigente antes de declarar.","summary":"Registre cada operação e confirme a regra oficial vigente antes de declarar.","duration":59.184,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m9l1', '{"paragraphs":["No mercado à vista, uma compra pode resultar em saldo do ativo, sujeito à custódia usada. Um contrato futuro cria exposição às variações de preço segundo especificações próprias; ele não significa necessariamente receber Bitcoin. Na B3, por exemplo, contratos futuros de Bitcoin têm liquidação financeira. Contratos e regras variam por mercado.","Long (posição comprada) tende a ganhar com a alta do contrato e perder com a queda; short (posição vendida) tende ao contrário. Ambos são exposições: o preço pode se mover na direção oposta, e a perda pode crescer rapidamente. Short não é simplesmente “vender Bitcoin que você tem”.","Margem é garantia de cumprimento, não o preço total da exposição. Alavancagem amplifica a variação sobre o capital comprometido. Ajustes, taxas, margem de manutenção, funding em contratos perpétuos, vencimento e liquidação forçada dependem do produto e da plataforma. Leia a especificação atual antes de sequer simular."],"takeaway":"Long e short descrevem direção. Margem e alavancagem determinam como pequenas oscilações afetam a conta.","sources":[{"label":"B3: características técnicas do futuro de Bitcoin em reais","url":"https://www.b3.com.br/pt_br/produtos-e-servicos/negociacao/criptoativos/futuro-de-bitcoin-em-reais.htm"},{"label":"CFTC: riscos de operar futuros de criptomoedas com margem","url":"https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/understand_risks_of_virtual_currency.html"}],"exercise":{"title":"Interprete a posição","prompt":"Uma posição short está aberta e o preço do contrato sobe. Qual leitura é correta?","options":["A posição tende a perder, antes de custos e regras específicas","A posição ganha porque o ativo ficou mais caro","O efeito é sempre zero até a liquidação"],"note":"O resultado depende do tamanho, contrato, preço de entrada, ajustes e custos. A direção sozinha não calcula o risco total."},"narration":{"src":"/audio/narrated/m9l1-4466c5127d5a.mp3","captionsSrc":"/audio/narrated/m9l1-4466c5127d5a.json","transcript":"Spot, futuro e posição comprada ou vendida.\n\nNo mercado à vista, uma compra pode resultar em saldo do ativo, sujeito à custódia usada. Um contrato futuro cria exposição às variações de preço segundo especificações próprias; ele não significa necessariamente receber Bitcoin. Na B3, por exemplo, contratos futuros de Bitcoin têm liquidação financeira. Contratos e regras variam por mercado.\n\nLong (posição comprada) tende a ganhar com a alta do contrato e perder com a queda; short (posição vendida) tende ao contrário. Ambos são exposições: o preço pode se mover na direção oposta, e a perda pode crescer rapidamente. Short não é simplesmente “vender Bitcoin que você tem”.\n\nMargem é garantia de cumprimento, não o preço total da exposição. Alavancagem amplifica a variação sobre o capital comprometido. Ajustes, taxas, margem de manutenção, funding em contratos perpétuos, vencimento e liquidação forçada dependem do produto e da plataforma. Leia a especificação atual antes de sequer simular.\n\nPara guardar: Long e short descrevem direção. Margem e alavancagem determinam como pequenas oscilações afetam a conta.","summary":"Long e short descrevem direção. Margem e alavancagem determinam como pequenas oscilações afetam a conta.","duration":84.048,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m9l2', '{"paragraphs":["Padrões de mercado são formas de resumir o que ocorreu em um gráfico, não garantias sobre o que ocorrerá. Uma tendência de alta costuma ser descrita por máximas e mínimas ascendentes; em uma tendência de baixa, por máximas e mínimas descendentes. Em consolidação, preço oscila numa faixa observada.","Suporte e resistência são zonas aproximadas onde o preço encontrou oferta ou procura no passado. Um rompimento pode continuar, falhar ou voltar à faixa. Volume, volatilidade, liquidez, período analisado e notícias mudam a leitura; nenhuma linha prevê o próximo movimento.","Ao estudar um gráfico, escreva a hipótese e um cenário que a invalidaria. Compare períodos diferentes, identifique o que já se sabe depois do fato e teste a ideia em dados históricos sem escolher exemplos só porque funcionaram. Um padrão isolado não é recomendação de entrada."],"takeaway":"Leia padrões como hipóteses sobre dados passados; não como sinais certos de compra ou venda.","sources":[],"exercise":{"title":"Evite a certeza retrospectiva","prompt":"O preço rompeu uma resistência e depois recuou. O que essa observação permite concluir?","options":["O rompimento falhou naquele trecho; um evento não prova regra futura","Todo próximo rompimento também falhará","O gráfico garante uma reversão para baixo"],"note":"Registre contexto, período e critérios antes de avaliar padrões. Um exemplo isolado não estima probabilidade."},"narration":{"src":"/audio/narrated/m9l2-12c001e8b20f.mp3","captionsSrc":"/audio/narrated/m9l2-12c001e8b20f.json","transcript":"Tendência, suporte, resistência e rompimentos.\n\nPadrões de mercado são formas de resumir o que ocorreu em um gráfico, não garantias sobre o que ocorrerá. Uma tendência de alta costuma ser descrita por máximas e mínimas ascendentes; em uma tendência de baixa, por máximas e mínimas descendentes. Em consolidação, preço oscila numa faixa observada.\n\nSuporte e resistência são zonas aproximadas onde o preço encontrou oferta ou procura no passado. Um rompimento pode continuar, falhar ou voltar à faixa. Volume, volatilidade, liquidez, período analisado e notícias mudam a leitura; nenhuma linha prevê o próximo movimento.\n\nAo estudar um gráfico, escreva a hipótese e um cenário que a invalidaria. Compare períodos diferentes, identifique o que já se sabe depois do fato e teste a ideia em dados históricos sem escolher exemplos só porque funcionaram. Um padrão isolado não é recomendação de entrada.\n\nPara guardar: Leia padrões como hipóteses sobre dados passados; não como sinais certos de compra ou venda.","summary":"Leia padrões como hipóteses sobre dados passados; não como sinais certos de compra ou venda.","duration":70.992,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m9l3', '{"paragraphs":["Este laboratório usa valor nocional e movimento hipotético para mostrar como a direção e a alavancagem mudam o resultado aritmético. Ele não usa preços atuais, não estima chance de liquidação e não reproduz as regras de uma exchange ou contrato.","O resultado simplificado é nocional × variação do preço × direção. A margem inicial é aproximada por nocional ÷ alavancagem. Custos, funding, ajustes, margem de manutenção, slippage, gaps e regras de liquidação podem mudar muito o resultado real — e uma posição pode ser encerrada antes que o cenário selecionado aconteça.","Use a simulação para perguntar “quanto posso perder?” antes de perguntar “quanto posso ganhar?”. Futuros são instrumentos complexos e não são necessários para aprender sobre Bitcoin ou concluir esta trilha."],"takeaway":"Simulação de alavancagem ensina escala de risco; não encontra entrada nem sugere operar.","sources":[{"label":"B3: especificações atuais do futuro de Bitcoin","url":"https://www.b3.com.br/pt_br/produtos-e-servicos/negociacao/criptoativos/futuro-de-bitcoin-em-reais.htm"},{"label":"CFTC: alavancagem pode ampliar perdas e exigir mais margem","url":"https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/understand_risks_of_virtual_currency.html"}],"exercise":{"title":"Leia a escala","prompt":"Em uma exposição nocional hipotética de R$ 1.000, o preço se move 5% contra uma posição. O que a alavancagem altera primeiro?","options":["O valor nocional exposto em relação à margem e a perda como proporção dela","A direção do movimento de preço","A certeza de lucro na operação seguinte"],"note":"Alavancagem não muda a variação do subjacente; muda a relação entre exposição, margem e resultado na conta."},"narration":{"src":"/audio/narrated/m9l3-d71f18845d39.mp3","captionsSrc":"/audio/narrated/m9l3-d71f18845d39.json","transcript":"Simulador de exposição e liquidação.\n\nEste laboratório usa valor nocional e movimento hipotético para mostrar como a direção e a alavancagem mudam o resultado aritmético. Ele não usa preços atuais, não estima chance de liquidação e não reproduz as regras de uma exchange ou contrato.\n\nO resultado simplificado é nocional × variação do preço × direção. A margem inicial é aproximada por nocional ÷ alavancagem. Custos, funding, ajustes, margem de manutenção, slippage, gaps e regras de liquidação podem mudar muito o resultado real — e uma posição pode ser encerrada antes que o cenário selecionado aconteça.\n\nUse a simulação para perguntar “quanto posso perder?” antes de perguntar “quanto posso ganhar?”. Futuros são instrumentos complexos e não são necessários para aprender sobre Bitcoin ou concluir esta trilha.\n\nPara guardar: Simulação de alavancagem ensina escala de risco; não encontra entrada nem sugere operar.","summary":"Simulação de alavancagem ensina escala de risco; não encontra entrada nem sugere operar.","duration":65.352,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m7l1', '{"paragraphs":["Euforia pode levar a comprar depois de uma alta; medo pode levar a vender no pior momento para seus objetivos. Alertas, redes sociais e gráficos em tempo real aumentam a pressão por uma decisão imediata.","Crie uma pausa operacional: escreva a tese, a perda possível, o tamanho e o que mudou. Espere até conseguir explicar a decisão sem depender de uma manchete ou de um influenciador.","Um diário de decisões registra expectativa, evidências e resultado. Ele ajuda a distinguir uma decisão coerente com as informações disponíveis de uma decisão que apenas terminou bem ou mal."],"takeaway":"Avalie a qualidade do processo, não apenas o resultado de uma operação.","sources":[],"exercise":{"title":"Pausa de decisão","prompt":"O ativo disparou e você sente que está ficando para trás. Qual é a pausa mais útil?","options":["Rever tese, tamanho e evidências antes de decidir","Comprar qualquer quantia imediatamente","Ignorar o orçamento porque a tendência está clara"],"note":"A pausa não prevê o preço; ela impede que urgência substitua seu próprio critério."},"narration":{"src":"/audio/narrated/m7l1-4c4220bdcd1b.mp3","captionsSrc":"/audio/narrated/m7l1-4c4220bdcd1b.json","transcript":"Decida fora do ruído.\n\nEuforia pode levar a comprar depois de uma alta; medo pode levar a vender no pior momento para seus objetivos. Alertas, redes sociais e gráficos em tempo real aumentam a pressão por uma decisão imediata.\n\nCrie uma pausa operacional: escreva a tese, a perda possível, o tamanho e o que mudou. Espere até conseguir explicar a decisão sem depender de uma manchete ou de um influenciador.\n\nUm diário de decisões registra expectativa, evidências e resultado. Ele ajuda a distinguir uma decisão coerente com as informações disponíveis de uma decisão que apenas terminou bem ou mal.\n\nPara guardar: Avalie a qualidade do processo, não apenas o resultado de uma operação.","summary":"Avalie a qualidade do processo, não apenas o resultado de uma operação.","duration":48.744,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m7l2', '{"paragraphs":["Uma política pessoal pode caber em uma página. Inclua seu objetivo de aprendizagem, horizonte, dinheiro que não será comprometido, limites de exposição, custódia, frequência de revisão e condições para interromper uma operação.","Registre o que você ainda não sabe. Decida que fontes consulta, como guarda comprovantes e qual sinal faria a tese perder validade. Regras são úteis quando conseguem ser lembradas sob pressão.","Revise a política com eventos da vida e fatos relevantes, não por causa de todo movimento diário. Se não conseguir cumprir as regras escritas, ajuste o tamanho e a complexidade."],"takeaway":"Um plano pessoal começa com limites e perguntas, não com uma lista de moedas.","sources":[],"exercise":{"title":"Complete uma regra","prompt":"Qual frase forma um limite verificável?","options":["“Vou investir o que for preciso.”","“Não uso dinheiro de contas ou reserva; reviso a tese no primeiro domingo do mês.”","“Vendo quando achar que está caro.”"],"note":"Uma regra clara descreve o que fazer e quando revisar."},"narration":{"src":"/audio/narrated/m7l2-7957d29a7af8.mp3","captionsSrc":"/audio/narrated/m7l2-7957d29a7af8.json","transcript":"Escreva sua política pessoal.\n\nUma política pessoal pode caber em uma página. Inclua seu objetivo de aprendizagem, horizonte, dinheiro que não será comprometido, limites de exposição, custódia, frequência de revisão e condições para interromper uma operação.\n\nRegistre o que você ainda não sabe. Decida que fontes consulta, como guarda comprovantes e qual sinal faria a tese perder validade. Regras são úteis quando conseguem ser lembradas sob pressão.\n\nRevise a política com eventos da vida e fatos relevantes, não por causa de todo movimento diário. Se não conseguir cumprir as regras escritas, ajuste o tamanho e a complexidade.\n\nPara guardar: Um plano pessoal começa com limites e perguntas, não com uma lista de moedas.","summary":"Um plano pessoal começa com limites e perguntas, não com uma lista de moedas.","duration":52.44,"voice":"pt-BR-AntonioNeural"}}'::jsonb),
  ('m7l3', '{"paragraphs":["Na primeira semana, revise segurança e faça seu orçamento de estudo. Na segunda, compare duas teses usando as mesmas perguntas. Na terceira, pratique uma transferência em ambiente de teste ou com simulação. Na quarta, reveja o que aprendeu e atualize sua política.","Não precisa abrir conta, comprar um ativo ou entrar em DeFi para concluir o curso. O próximo passo pode ser estudar mais, conversar com um profissional ou decidir que o risco não combina com seus objetivos.","Parabéns por concluir a trilha. Seu certificado registra participação no curso; não atesta rentabilidade, habilitação profissional ou domínio completo do mercado."],"takeaway":"Estudar com método também significa reconhecer quando não agir.","sources":[],"exercise":{"title":"Escolha seu próximo passo","prompt":"Qual sequência representa melhor uma continuação responsável?","options":["Revisar orçamento, segurança e evidências antes de tomar qualquer decisão","Comprar o ativo mais comentado no dia","Prometer retorno a outras pessoas"],"note":"O curso é educativo. Cada pessoa deve considerar seu contexto e os riscos."},"narration":{"src":"/audio/narrated/m7l3-6de0c70ec81a.mp3","captionsSrc":"/audio/narrated/m7l3-6de0c70ec81a.json","transcript":"Seu roteiro de 30 dias.\n\nNa primeira semana, revise segurança e faça seu orçamento de estudo. Na segunda, compare duas teses usando as mesmas perguntas. Na terceira, pratique uma transferência em ambiente de teste ou com simulação. Na quarta, reveja o que aprendeu e atualize sua política.\n\nNão precisa abrir conta, comprar um ativo ou entrar em DeFi para concluir o curso. O próximo passo pode ser estudar mais, conversar com um profissional ou decidir que o risco não combina com seus objetivos.\n\nParabéns por concluir a trilha. Seu certificado registra participação no curso; não atesta rentabilidade, habilitação profissional ou domínio completo do mercado.\n\nPara guardar: Estudar com método também significa reconhecer quando não agir.","summary":"Estudar com método também significa reconhecer quando não agir.","duration":54.456,"voice":"pt-BR-AntonioNeural"}}'::jsonb)
