-- Keep lesson bodies, answer keys, transcripts, and audio references behind course entitlement checks.
create table public.lesson_exercise_keys (
  lesson_id text primary key references public.lessons (id) on delete cascade,
  answer_index smallint not null check (answer_index >= 0)
);
alter table public.lesson_exercise_keys enable row level security;
revoke all on table public.lesson_exercise_keys from public, anon, authenticated;

revoke all on table public.lesson_content from public, anon, authenticated;
grant select on public.lesson_content to authenticated;

create or replace function public.verify_lesson_exercise(p_lesson_id text, p_answer_index integer)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  expected_answer smallint;
begin
  if (select auth.uid()) is null or not (select public.has_active_course_access()) then
    raise exception 'Active course access required.' using errcode = '42501';
  end if;
  select answer.answer_index into expected_answer
  from public.lesson_exercise_keys as answer
  join public.lessons as lesson on lesson.id = answer.lesson_id and lesson.published
  where answer.lesson_id = p_lesson_id;
  if not found then
    raise exception 'Published exercise not found.' using errcode = '22023';
  end if;
  return expected_answer = p_answer_index;
end;
$$;
revoke all on function public.verify_lesson_exercise(text, integer) from public, anon;
grant execute on function public.verify_lesson_exercise(text, integer) to authenticated;

on conflict (lesson_id) do update set content = excluded.content, updated_at = now();

on conflict (lesson_id) do update set answer_index = excluded.answer_index;
